import java.util.*;
​
public class Main {
    // 计算两个一维数组的点积
    private static double dotProduct(List<Double> a, List<Double> b) {
        double result = 0.0;
        for (int i = 0; i < a.size(); i++) {
            result += a.get(i) * b.get(i);
        }
        return result;
    }
​
    // 根据不等式约束判断是否满足条件
    private static boolean satisfiesConstraint(double val, String constraint) {
        switch (constraint) {
            case ">": return val > 0;
            case ">=": return val >= 0;
            case "<": return val < 0;
            case "<=": return val <= 0;
            case "=": return val == 0;
            default: return false;
        }
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextLine()) {
            String line = scanner.nextLine();
            String[] arr = line.split(";");

            List<List<Double>> matrix = new ArrayList<>();
            List<Double> x = new ArrayList<>();
            List<Double> b = new ArrayList<>();
            List<String> y = new ArrayList<>();
​
            // 解析矩阵
            for (int i = 0; i < 3; i++) {
                matrix.add(parseDoubles(arr[i]));
            }

            // 解析 x, b, y
            x = parseDoubles(arr[3]);
            b = parseDoubles(arr[4]);
            y = Arrays.asList(arr[5].split(","));

            // 计算不等式的差值
            List<Double> diffs = new ArrayList<>();
            for (int i = 0; i < 3; i++) {
                diffs.add(dotProduct(matrix.get(i), x) - b.get(i));
            }

            // 判断所有不等式是否成立
            boolean flag = satisfiesConstraint(diffs.get(0), y.get(0)) &&
                           satisfiesConstraint(diffs.get(1), y.get(1)) &&
                           satisfiesConstraint(diffs.get(2), y.get(2));

            // 计算最大差值的整数部分
            int maxDiff = (int) Math.max(Math.abs(diffs.get(0)),
                                Math.max(Math.abs(diffs.get(1)), Math.abs(diffs.get(2))));

            System.out.println((flag ? "true" : "false") + " " + maxDiff);
        }
        scanner.close();
    }
​
    // 辅助方法: 将逗号分隔的字符串转换为 double 列表
    private static List<Double> parseDoubles(String input) {
        List<Double> result = new ArrayList<>();
        for (String s : input.split(",")) {
            result.add(Double.parseDouble(s));
        }
        return result;
    }
}

