// 根据不等式约束判断一个数是否大于、大于等于、小于、小于等于、等于 0
bool satisfiesConstraint(double val, string constraint) {
    if (constraint == ">") {
        return val > 0;
    }
    else if (constraint == ">=") {
        return val >= 0;
    }
    else if (constraint == "<") {
        return val < 0;
    }
    else if (constraint == "<=") {
        return val <= 0;
    }
    else if (constraint == "=") {
        return val == 0;
    }
    else {
        return false;
    }
}
